/**
 * Measure vertical icon/text alignment inside the actual WhatsApp-share PNG
 * generated by html2canvas, by loading the invoice HTML in a real browser and
 * running html2canvas, then inspecting bounding boxes.
 *
 * Usage: node tools/measure-h2c-icons.mjs
 */
import puppeteer from 'puppeteer';
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';

const dir = path.resolve('storage/app/invoice-qa');
const root = path.resolve('.');

const types = { '.html': 'text/html; charset=utf-8', '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.webp': 'image/webp', '.js': 'text/javascript', '.css': 'text/css' };
const server = http.createServer((req, res) => {
    const url = decodeURIComponent(req.url.split('?')[0]);
    const target = path.join(root, url.replace(/^\/+/, ''));
    if (!target.startsWith(root) || !fs.existsSync(target) || fs.statSync(target).isDirectory()) { res.writeHead(404); res.end(); return; }
    res.writeHead(200, { 'Content-Type': types[path.extname(target)] || 'application/octet-stream' });
    fs.createReadStream(target).pipe(res);
});
await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
const port = server.address().port;
const pageUrl = `http://127.0.0.1:${port}/${path.relative(root, path.join(dir, 'base.html')).replace(/\\/g, '/')}`;

const browser = await puppeteer.launch({ headless: true, args: ['--no-sandbox', '--disable-setuid-sandbox'] });
try {
    const page = await browser.newPage();
    await page.setViewport({ width: 1440, height: 1200, deviceScaleFactor: 1 });
    await page.goto(pageUrl, { waitUntil: 'networkidle0' });
    await page.addScriptTag({ path: path.resolve('node_modules/html2canvas/dist/html2canvas.min.js') });

    const rows = await page.evaluate(async () => {
        const invoice = document.querySelector('.invoice-doc');
        const host = document.createElement('div');
        host.style.cssText = 'position:fixed;left:-10000px;top:0;width:794px;height:1123px;z-index:-1;';
        const wrap = document.createElement('div');
        wrap.style.cssText = 'box-sizing:border-box;width:100%;padding:40px 42px;background:#fff;';
        wrap.append(invoice.cloneNode(true));
        host.append(wrap);
        document.body.append(host);

        const canvas = await window.html2canvas(wrap, { backgroundColor: '#FFFFFF', scale: 1, windowWidth: 794, useCORS: true, logging: false });
        host.remove();

        // Reopen the same clone to read real DOM geometry (what html2canvas paints).
        // html2canvas rasterizes the live DOM, so getBoundingClientRect is the ground truth.
        const clone = invoice.cloneNode(true);
        document.body.append(clone);

        const results = [];
        const icons = clone.querySelectorAll('svg');

        icons.forEach((icon) => {
            let row = icon.parentElement;
            while (row && getComputedStyle(row).display !== 'flex') {
                row = row.parentElement;
                if (!row || row === clone) { row = null; break; }
            }
            if (!row) return;
            const iconRect = icon.getBoundingClientRect();
            const texts = Array.from(row.querySelectorAll('span, div')).filter((el) => el !== icon && el.children.length === 0 && el.textContent.trim());
            const text = texts.reduce((best, el) => (!best || el.getBoundingClientRect().width > best.getBoundingClientRect().width ? el : best), null);
            if (!text) return;
            const textRect = text.getBoundingClientRect();
            results.push({
                text: text.textContent.trim().slice(0, 40),
                iconCenter: +((iconRect.top + iconRect.bottom) / 2).toFixed(1),
                textCenter: +((textRect.top + textRect.bottom) / 2).toFixed(1),
                diff: +(((iconRect.top + iconRect.bottom) / 2) - ((textRect.top + textRect.bottom) / 2)).toFixed(1),
            });
        });

        clone.remove();
        return results;
    });

    rows.forEach((r) => {
        const flag = Math.abs(r.diff) > 1.5 ? '  <-- OFF' : '';
        process.stdout.write(`diff=${String(r.diff).padStart(6)}  ${JSON.stringify(r.text)}${flag}\n`);
    });
} finally {
    await browser.close();
    server.close();
}
